{
  "nodes": [
    {
      "id": "Start",
      "text": "The tavern door creaks open. Smoke and laughter fill the air.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "TavernEntry",
      "text": "Three figures catch your eye: a hooded stranger, a boisterous merchant, and the barkeep.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "TavernChoice",
      "text": "1. Approach the hooded stranger.\n2. Sit next to the merchant.\n3. Order a drink from the barkeep.\n4. [Observe] Study the room from the shadows.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "ObserveRoom",
      "text": "You notice the stranger slipping a note to the barkeep. The merchant counts gold nervously.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "ObserveChoice",
      "text": "1. Intercept the note.\n2. Pickpocket the merchant.\n3. Pretend you saw nothing.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "InterceptNote",
      "text": "You dare?!",
      "speaker": "Stranger",
      "type": "line"
    },
    {
      "id": "PickpocketAttempt",
      "text": "1. [Sleight of Hand] Swiftly grab the pouch.\n2. [Distraction] Bump into him accidentally.\n3. Abandon the attempt.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "PickpocketSuccess",
      "text": "50 gold pieces heavier, you slip away. The merchant hasn't noticed... yet.",
      "speaker": "Narrator",
      "type": "line"
    },

